import{_ as o,a as i,b as t,c as e,d as r}from"./chunks/device-tablet-landscape.C-4EbIkT.js";import{_ as s,o as n,c as p,a2 as c}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"デバイスごとの表示","description":"同じアプリが、いくつもの姿に。KomaYomi は別のモバイル版で機能を隠すのではなく、画面幅に合わせて組み替えます。ボタンはどれも画面のどこかにいて、ただ場所を変えるだけです。このページでは、主要なウィンドウが各サイズでどう並ぶかをまとめます。どのサイズにも実際のキャプチャを添えています。","frontmatter":{"description":"同じアプリが、いくつもの姿に。KomaYomi は別のモバイル版で機能を隠すのではなく、画面幅に合わせて組み替えます。ボタンはどれも画面のどこかにいて、ただ場所を変えるだけです。このページでは、主要なウィンドウが各サイズでどう並ぶかをまとめます。どのサイズにも実際のキャプチャを添えています。"},"headers":[],"relativePath":"ja/guide/devices.md","filePath":"ja/guide/devices.md","lastUpdated":1794842635000}'),l={name:"ja/guide/devices.md"};function d(h,a,m,g,u,f){return n(),p("div",null,[...a[0]||(a[0]=[c('<h1 id="デバイスごとの表示" tabindex="-1">デバイスごとの表示 <a class="header-anchor" href="#デバイスごとの表示" aria-label="Permalink to &quot;デバイスごとの表示&quot;">​</a></h1><p>同じアプリが、いくつもの姿に。KomaYomi は別のモバイル版で機能を隠すのではなく、画面幅に合わせて組み替えます。ボタンはどれも画面のどこかにいて、ただ場所を変えるだけです。このページでは、主要なウィンドウが各サイズでどう並ぶかをまとめます。どのサイズにも実際のキャプチャを添えています。</p><h2 id="pc-横向き-—-1440-px" tabindex="-1">PC 横向き — 1440 px <a class="header-anchor" href="#pc-横向き-—-1440-px" aria-label="Permalink to &quot;PC 横向き — 1440 px&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="幅 1440 px のウィンドウ：左にライブラリのサイドバー、中央に 3 つの比較ペイン、右にノート列"><figcaption>1440 px：左がサイドバー、中央が 3 言語の並列、右がノート列。</figcaption></figure><p>1440 px ではサイドバー（約 270 px）、比較ステージ、ノート列が同時に見えます。3 言語のペインが横に並ぶので、ひと続きのやり取りがスクロールなしで収まります。幅が 1180 px を超える状態で起動するとノート列は既定で開き、仕切りをドラッグすれば広げられ、<strong>ノート</strong>（<code>N</code>）で閉じられます。</p><h2 id="pc-縦向き-—-900-×-1200" tabindex="-1">PC 縦向き — 900 × 1200 <a class="header-anchor" href="#pc-縦向き-—-900-×-1200" aria-label="Permalink to &quot;PC 縦向き — 900 × 1200&quot;">​</a></h2><figure class="shot"><img src="'+i+'" alt="900 × 1200 の狭いウィンドウ：ライブラリがドロワーに畳まれ、比較ペインが縦に積まれる"><figcaption>900 × 1200：サイドバーはドロワーへ、比較は 1 列、ノート列は既定で閉じています。</figcaption></figure><p>900 px になると狭い画面モードに入ります。ライブラリは ☰ ボタンの後ろのドロワーに畳まれ、比較ペインは 1 列に縦積みになり、ノート列は既定で閉じます（<strong>ノート</strong> で呼び戻せます）。ツールバーのグループは文字ラベルを落とし、入りきらない操作は <strong>More</strong> に移ります。</p><h2 id="スマートフォン縦向き-—-390-×-844" tabindex="-1">スマートフォン縦向き — 390 × 844 <a class="header-anchor" href="#スマートフォン縦向き-—-390-×-844" aria-label="Permalink to &quot;スマートフォン縦向き — 390 × 844&quot;">​</a></h2><figure class="shot"><img src="'+t+'" alt="390 × 844 のウィンドウ：トップバーとツールバーが複数行に折り返した様子"><figcaption>390 × 844：トップバーが 3 行、ツールバーも複数行に折り返し、タッチレイアウトでは言語レーンを 1 本ずつ表示します。</figcaption></figure><p>390 px のタッチスマートフォンでは、トップバーが 3 行に折り返します。ナビゲーションとページ操作、次に UI 言語と書き出し、最後に <strong>Panels / Compare</strong> の切り替えです。比較ステージは言語レーンを 1 本ずつ表示します。ステージ上の言語タブバー（JA / EN / ZH）で、有効な言語のどれを表示するかを選びます。2 言語以上が有効なときは左右スワイプでも切り替えられ、タブの横にそのヒントが出ます。ツールバーの言語トグルは、そもそもどの言語を有効にするかを決めます。ツールバーのグループは横スクロールで消えるのではなく次の行へ折り返し、ライブラリは左ドロワー、ノートは全幅ドロワーで開きます。スマートフォンを横向きにすると、タブレット縦向きと同じ 2 レーンのタッチレイアウトになります。</p><h2 id="タブレット縦向き-—-820-×-1180" tabindex="-1">タブレット縦向き — 820 × 1180 <a class="header-anchor" href="#タブレット縦向き-—-820-×-1180" aria-label="Permalink to &quot;タブレット縦向き — 820 × 1180&quot;">​</a></h2><figure class="shot"><img src="'+e+'" alt="820 × 1180 のウィンドウ：トップバーは 1 行、比較ペインは縦積み"><figcaption>820 × 1180：トップバーは 1 行、サイドバーはドロワー。マウス操作のウィンドウではペインが縦積みになり、タッチタブレットでは 2 列に並びます。</figcaption></figure><p>KomaYomi の比較レイアウトは、幅だけでなくポインターの種類とアスペクト比で決まります。820 px のマウス操作ウィンドウでは、ペインは 1 列に縦積みになります。タッチタブレットの縦向きでは、各コマに言語レーンが 2 本並びます。3 言語以上が有効なときは、ステージ上のタブバーが表示する 2 本を選び、フォーカス中の言語から始まります。幅 900 px 以下のスマートフォン横向きも同じ 2 レーンのレイアウトです。トップバーは 1 行のまま、サイドバーはドロワーのまま、ツールバーは折り返して入りきらない操作を <strong>More</strong> に畳み、ノートはステージの上にドロワーで開きます。</p><h2 id="タブレット横向き-—-1180-×-820" tabindex="-1">タブレット横向き — 1180 × 820 <a class="header-anchor" href="#タブレット横向き-—-1180-×-820" aria-label="Permalink to &quot;タブレット横向き — 1180 × 820&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="1180 × 820 のタブレット画面：サイドバーが開き、3 言語のペインが横に並ぶ"><figcaption>1180 × 820：サイドバーが開き、3 言語が横並び、ノートはドロワー。</figcaption></figure><p>1180 px ではサイドバー（240 px）が戻り、3 言語のペインが横 1 列に並びます（各約 290 px）。タッチタブレットの横向きでは、幅 900 px 以下は 2 レーン、900 px を超えて 1199 px までが 3 レーンです。言語タブバーはレーン数より多くの言語が有効なときだけ現れます。この幅でもノートはドロワーで、開くとステージの上に重なります。ツールバーは 2 段のままで、上段が言語と位置合わせ、下段が注釈ツールです。<strong>Export HTML</strong> はトップバーに残ります。</p><div class="info custom-block"><p class="custom-block-title">スマートフォンとタブレット縦向きのキャプチャについて</p><p>上の 390 × 844 と 820 × 1180 のキャプチャはマウス操作のブラウザウィンドウで撮影したため、デスクトップ側の縦積みルールが写っています。タッチのスマートフォンやタブレットでは、このページで説明しているタッチレイアウトになります。スマートフォンは 1 レーン、タブレット縦向きは 2 レーンを並べます。</p></div><div class="tip custom-block"><p class="custom-block-title">自分で撮るときは</p><p>ページのズームではなくブラウザのウィンドウを直接リサイズしてください。ブレークポイントはビューポート幅を見ており、サイドバーとノート列はウィンドウ自体がブレークポイントを越えたときだけ入れ替わります。</p></div><h2 id="ネイティブモバイルアプリ" tabindex="-1">ネイティブモバイルアプリ <a class="header-anchor" href="#ネイティブモバイルアプリ" aria-label="Permalink to &quot;ネイティブモバイルアプリ&quot;">​</a></h2><p>上で説明したのはブラウザー版のレスポンシブレイアウトです。別リポジトリにはネイティブアプリ <a href="https://github.com/PayayaKamo/KomaYomi-mobile" target="_blank" rel="noopener noreferrer">KomaYomi-mobile</a> があり、Android と iOS に対応しています。同じ <code>.mnproj</code> を開き、変更はプロジェクトファイルへ書き戻します。</p><h3 id="_0-2-1-大きなプロジェクトの読み込みを高速化" tabindex="-1">0.2.1：大きなプロジェクトの読み込みを高速化 <a class="header-anchor" href="#_0-2-1-大きなプロジェクトの読み込みを高速化" aria-label="Permalink to &quot;0.2.1：大きなプロジェクトの読み込みを高速化&quot;">​</a></h3><p>以前はスマートフォンで大きな <code>.mnproj</code> を開くと、時間のかかる処理がすべて JavaScript 側にありました。アーカイブをメモリ上で展開し、数千枚のページ画像を展開する間 UI が固まることがありました。<strong>0.2.1</strong> の Android 版はアーカイブをネイティブの Kotlin 展開処理に渡します。JavaScript が読むのは小さな JSON だけで、画像は JS ブリッジを通さずディスク上で移動します。読み込み画面には段階（読み取り、展開、画像、保存）が表示されるため、時間がかかっても固まったようには見えません。</p><p>iOS 版は今もメモリ上で展開するため、非常に大きなプロジェクトでは以前の Android 版と同じ挙動になります。読み込みが中断された場合、リンクは残りません。中途半端に展開されたコピーを編集せず、もう一度プロジェクトを開いてください。</p><h3 id="期待できること" tabindex="-1">期待できること <a class="header-anchor" href="#期待できること" aria-label="Permalink to &quot;期待できること&quot;">​</a></h3><ul><li><strong>Android</strong> — ユニバーサル APK、ABI 別 APK、AAB を公開しています。公開ビルドは debug keystore を使うため、サイドロードには向きますがストア公開には使えず、別の鍵で署名したビルドの上から更新インストールもできません。</li><li><strong>iOS</strong> — ローカルで署名してビルドしてください。署名済み IPA の配布はありません。</li><li><strong>HarmonyOS NEXT</strong> — プレースホルダーで、まだ動作する対象ではありません。</li><li>モバイルアプリは既存プロジェクトの閲覧・編集用で、スキャナーではありません。フォルダーまたは <code>.mnproj</code> は先にパソコンで用意してください。</li></ul>',26)])])}const P=s(l,[["render",d]]);export{b as __pageData,P as default};
